from flax import linen as nn
@nn.compact
class CNNModel(nn.Module):
    def __init__(self, num_filters, filter_size, strides, padding):
        super().__init__()
        self.conv = nn.Conv(num_filters, filter_size, strides, padding))

    def forward(self, x)):

        x = jnp.asarray(x))

        x = self.relu(self.conv1(x))

        x = self.pool(self.relu(self.conv2(x))))
